import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"字节码解释器","description":"","frontmatter":{"title":"字节码解释器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bytecode-interpreter.md","filePath":"cs/bytecode-interpreter.md","lastUpdated":1789023840000}'),h={name:"cs/bytecode-interpreter.md"};function m(f,a,_,u,A,E){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="字节码解释器" tabindex="-1">字节码解释器 <a class="header-anchor" href="#字节码解释器" aria-label="Permalink to &quot;字节码解释器&quot;">​</a></h1><div class="epigraph"><p>编译到紧凑的字节码，再由循环取指、译码、执行。比树遍历快，比 native 慢；换来可移植与短生成时间。</p><footer>—— 据 Deutsch and Schiffman, Efficient Implementation of the Smalltalk-80 System；Appel；主干运行时直觉整理</footer></div><p>上一课<a href="/cs/cross-compile-triple">交叉编译</a> 把 native ELF 交到目标机。缺口是另一条交付：<strong>字节码 + 解释器</strong>。JVM、CPython、早期 Pascal P-code。本课钉分派循环，栈 vs 寄存器 VM 下一课。不重写 ELF 加载。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AST 解释：每结点虚调用，慢。字节码：线性指令、小操作码。循环：<code>op = *pc++; switch(op)</code>。缺口是<strong>这层 IR 的执行</strong>，不是 lex。</p><p>与<a href="/cs/operational-semantics">操作语义</a>：解释器是 SOS 的可执行版。正确性：每条字节码对应小步。</p><h3 id="字节码不是「源码压缩」" tabindex="-1">字节码不是「源码压缩」 <a class="header-anchor" href="#字节码不是「源码压缩」" aria-label="Permalink to &quot;字节码不是「源码压缩」&quot;">​</a></h3><p>它是编译器后端的另一种目标。类型检查仍在生成前。不要把 <code>.pyc</code> 当加密。</p><p><span class="marginnote">Deutsch–Schiffman 1984。Pascal P-machine。Java 虚拟机规范是工程百科，本课只取解释循环。不写 JIT，后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义操作码：load/store、算术、跳转、调用。生成器从 AST/IR 吐字节。解释器维护 PC、栈或寄存器文件、常量池。</p>',11)),(e(),n(d,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%22%5D%20--%3E%20BC%5B%22%E5%AD%97%E8%8A%82%E7%A0%81%22%5D%0A%20%20BC%20--%3E%20LOOP%5B%22%E5%8F%96%E6%8C%87%E8%AF%91%E7%A0%81%E6%89%A7%E8%A1%8C%22%5D%0A%20%20LOOP%20--%3E%20ST%5B%22%E6%A0%88%20%2F%20%E5%AF%84%E5%AD%98%E5%99%A8%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 GC：解释器必须能枚举根（栈槽类型图）。主干<a href="/cs/runtime-gc">运行时 GC</a> 已给根。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>switch 分派：分支预测差。线程化分派后课。安全：校验器（JVM）在加载时查栈高度，否则解释器可被坏码打崩。</p><p>不要在解释器里做全局优化；那是编译到字节码的中端。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 JVM 指令全集。后课默认：字节码循环是 VM 基线。下一课栈式对寄存器式编码。</p><p>也不把解释器当 bash。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>字节码解释器：可移植目标 + 分派循环。</li><li>对应操作语义的可执行形式。</li><li>分派开销是主要税，后课减。</li><li>出处：Deutsch and Schiffman, 1984；Appel；对照 Plotkin SOS。</li></ul>',9))])}const b=i(h,[["render",m]]);export{P as __pageData,b as default};
